{"command":"cat > /tmp/keccak.py <<'PY'
# Keccak-f1600 pure python (for probing)
RC=[0x0000000000000001,0x0000000000008082,0x800000000000808a,0x8000000080008000,0x000000000000808b,0x0000000080000001,0x8000000080008081,0x8000000000008009,0x000000000000008a,0x0000000000000088,0x0000000080008009,0x000000008000000a,0x000000008000808b,0x800000000000008b,0x8000000000008089,0x8000000000008003,0x8000000000008002,0x8000000000000080,0x000000000000800a,0x800000008000000a,0x8000000080008081,0x8000000000008080,0x0000000080000001,0x8000000080008008]
R=[[0,36,3,41,18],[1,44,10,45,2],[62,6,43,15,61],[28,55,25,21,56],[27,20,39,8,14]]
def rol(x,n):
    return ((x<<n)|(x>>(64-n))) & ((1<<64)-1) if n else x
def keccak_f(st):
    # st 25 ints index x+5y
    for rc in RC:
        C=[st[x]^st[x+5]^st[x+10]^st[x+15]^st[x+20] for x in range(5)]
        D=[C[(x-1)%5]^rol(C[(x+1)%5],1) for x in range(5)]
        for x in range(5):
            for y in range(5): st[x+5*y]^=D[x]
        B=[0]*25
        for x in range(5):
            for y in range(5):
                B[y+5*((2*x+3*y)%5)]=rol(st[x+5*y],R[x][y])
        for x in range(5):
            for y in range(5):
                st[x+5*y]=B[x+5*y]^((~B[((x+1)%5)+5*y]) & B[((x+2)%5)+5*y])
        st[0]^=rc
        for i in range(25): st[i]&= (1<<64)-1
    return st
def keccak256(data=b""):
    rate=136
    # pad10*1 with 0x01 domain (keccak)
    padded=bytearray(data)
    padded.append(0x01)
    while len(padded)%rate!=0: padded.append(0)
    padded[-1]|=0x80
    st=[0]*25
    for off in range(0,len(padded),rate):
        block=padded[off:off+rate]
        for i in range(rate//8):
            lane=int.from_bytes(block[i*8:(i+1)*8],"little")
            st[i]^=lane
        keccak_f(st)
    out=b""
    while len(out)<32:
        for i in range(rate//8):
            out+=st[i].to_bytes(8,"little")
        if len(out)>=32: break
        keccak_f(st)
    return out[:32]
if __name__=="__main__":
    import sys
    for s in sys.argv[1:]:
        print(s, keccak256(s.encode()).hex())
PY
