def parse_usize_rust(s):
    if s == "":
        raise TypeParseInt("Empty", "cannot parse integer from empty string")
    bs = s.encode("utf-8", "surrogateescape")
    i = 0
    if bs[0:1] == b"+":
        i = 1
        if i >= len(bs):
            raise TypeParseInt("InvalidDigit", "invalid digit found in string")
    val = 0
    while i < len(bs):
        c = bs[i]
        if c < 48 or c > 57:
            raise TypeParseInt("InvalidDigit", "invalid digit found in string")
        val = val * 10 + (c - 48)
        if val > MAX_USIZE:
            raise TypeParseInt("PosOverflow", "number too large to fit in target type")
        i += 1
    return val

def _split_tuple_parts(inner):
    parts = []
    depth = 0
    start = 0
    for i, ch in enumerate(inner):
        if ch == "(" or ch == "[":
            depth += 1
        elif ch == ")" or ch == "]":
            depth -= 1
        elif ch == "," and depth == 0:
            parts.append(inner[start:i])
            start = i + 1
    parts.append(inner[start:])
    return parts

def read_param_type(s):
    # array suffix (checked first, as in observed behaviour for types ending in ])
    if s.endswith("]"):
        idx = s.rfind("[")
        if idx == -1:
            raise TypeParseInt("InvalidDigit", "invalid digit found in string")
        size_s = s[idx+1:-1]
        base_s = s[:idx]
        if size_s == "":
            return pt_array(read_param_type(base_s))
        size = parse_usize_rust(size_s)
        return pt_fixed_array(read_param_type(base_s), size)
    if s.endswith(")"):
        if not s.startswith("("):
            raise TypeInvalidName(s)
        inner = s[1:-1]
        parts = _split_tuple_parts(inner)
        types = []
        for part in parts:
            if part == "":
                continue
            if part.lstrip() == "()":
                continue
            try:
                types.append(read_param_type(part))
            except TypeInvalidName:
                raise TypeInvalidName(s)
        return pt_tuple(types)
    if s == "address":
        return pt_address()
    if s == "bool":
        return pt_bool()
    if s == "string":
        return pt_string()
    if s == "tuple":
        return pt_tuple([])
    if s.startswith("bytes"):
        suffix = s[5:]
        if suffix == "":
            return pt_bytes()
        return pt_fixed_bytes(parse_usize_rust(suffix))
    if s.startswith("int"):
        suffix = s[3:]
        if suffix == "":
            return pt_int(256)
        return pt_int(parse_usize_rust(suffix))
    if s.startswith("uint"):
        suffix = s[4:]
        if suffix == "":
            return pt_uint(256)
        return pt_uint(parse_usize_rust(suffix))
    return pt_uint(8)

