    return False

# ---------------------------------------------------------------- hex / numeric helpers
def _hex_val(bch):
    if 48 <= bch <= 57: return bch - 48
    if 97 <= bch <= 102: return bch - 87
    if 65 <= bch <= 70: return bch - 55
    return None

def hex_decode(s):
    bs = s.encode("utf-8", "surrogateescape") if isinstance(s, str) else s
    if len(bs) % 2 == 1:
        raise HexDecodeError("Odd number of digits")
    out = bytearray()
    for i in range(0, len(bs), 2):
        v1 = _hex_val(bs[i])
        if v1 is None:
            raise HexDecodeError("Invalid character '%s' at position %d" % (chr(bs[i]), i))
        v2 = _hex_val(bs[i+1])
        if v2 is None:
            raise HexDecodeError("Invalid character '%s' at position %d" % (chr(bs[i+1]), i+1))
        out.append((v1 << 4) | v2)
    return bytes(out)

def hex_decode_wrapped(s):
    try:
        return hex_decode(s)
    except HexDecodeError as e:
        raise AppError("Hex parsing error: " + e.msg, e.msg)

def hex_decode_plain(s):
    try:
        return hex_decode(s)
    except HexDecodeError as e:
        raise AppError(e.msg)

def strip_0x(s):
    if s.startswith("0x"):
