    return s

def parse_u256_dec(s):
    bs = s.encode("utf-8", "surrogateescape")
    val = 0
    for bch in bs:
        if bch < 48 or bch > 57:
            raise UintParseError("InvalidCharacter")
        val = val * 10 + (bch - 48)
        if val > MAX_U256:
            raise UintParseError("InvalidLength")
    return val

def parse_u256_hex(s):
    bs = s.encode("utf-8", "surrogateescape")
    val = 0
    for bch in bs:
        v = _hex_val(bch)
        if v is None:
            raise UintParseError("InvalidCharacter")
        val = (val << 4) | v
        if val > MAX_U256:
            raise UintParseError("InvalidLength")
    return val

def _bytes_len(s):
    return len(s.encode("utf-8", "surrogateescape"))

