    if k == "address": return v.hex()
    if k == "bool": return "true" if v else "false"
    if k == "string": return v
    if k == "bytes": return v.hex()
    if k == "fixedbytes": return v.hex()
    if k in ("uint", "int"): return "%x" % v
    if k in ("array", "fixedarray"):
        return "[" + ",".join(token_display(x) for x in v) + "]"
    if k == "tuple":
        return "(" + ",".join(token_display(x) for x in v) + ")"
    raise AssertionError(k)

def _split_token_parts(inner):
    parts = []
    depth = 0
    start = 0
    for i, ch in enumerate(inner):
        if ch == "(" or ch == "[":
            depth += 1
        elif ch == ")" or ch == "]":
            if depth == 0:
                raise invalid_data()
            depth -= 1
        elif ch == "," and depth == 0:
            parts.append(inner[start:i])
            start = i + 1
    parts.append(inner[start:])
    return parts

