    k = ptype[0]
    try:
        return _read_token(ptype, value, lenient)
    except UintParseError as e:
        raise AppError("Uint parse error: " + e.variant)

def _read_token(ptype, value, lenient):
    k = ptype[0]
    if k == "address":
        b = hex_decode_wrapped(strip_0x(value))
        if len(b) != 20:
            raise invalid_data()
        return Token("address", b)
    if k == "bool":
        if value in ("true", "1"):
            return Token("bool", True)
        if value in ("false", "0"):
            return Token("bool", False)
        raise invalid_data()
    if k == "string":
        return Token("string", value)
    if k == "bytes":
        return Token("bytes", hex_decode_wrapped(strip_0x(value)))
    if k == "uint":
        if lenient:
            if _bytes_len(value) == 64:
                return Token("uint", parse_u256_hex(value))
            return Token("uint", parse_u256_dec(value))
        b = hex_decode_wrapped(value)
        if len(b) != 32:
            raise invalid_data()
        return Token("uint", int.from_bytes(b, "big"))
    if k == "int":
        if lenient:
            if value.startswith("-"):
                mag = parse_u256_dec(value.lstrip("-"))
                if mag > (1 << 255):
                    raise AppError("int256 parse error: Underflow")
                return Token("int", ((1 << 256) - mag) & MAX_U256 if mag != 0 else 0)
            if _bytes_len(value) == 64:
                return Token("int", parse_u256_hex(value))
            mag = parse_u256_dec(value)
            if mag > (1 << 255) - 1:
                raise AppError("int256 parse error: Overflow")
            return Token("int", mag)
        b = hex_decode_wrapped(value)
        if len(b) != 32:
            raise invalid_data()
        return Token("int", int.from_bytes(b, "big"))
    if k == "fixedbytes":
        b = hex_decode_wrapped(strip_0x(value))
        if len(b) != ptype[1]:
            raise invalid_data()
        return Token("fixedbytes", b)
    if k == "array":
        if not (value.startswith("[") and value.endswith("]")):
            raise invalid_data()
        inner = value[1:-1]
        if inner == "":
            return Token("array", [])
        parts = _split_token_parts(inner)
        return Token("array", [read_token(ptype[1], p, lenient) for p in parts])
    if k == "fixedarray":
        if not (value.startswith("[") and value.endswith("]")):
            raise invalid_data()
        inner = value[1:-1]
        if inner == "":
            toks = []
        else:
            parts = _split_token_parts(inner)
            toks = [read_token(ptype[1], p, lenient) for p in parts]
        if len(toks) != ptype[2]:
            raise invalid_data()
        return Token("fixedarray", toks)
    if k == "tuple":
        if not (value.startswith("(") and value.endswith(")")):
            raise invalid_data()
        inner = value[1:-1]
        if inner == "":
            return Token("tuple", [])
        parts = _split_token_parts(inner)
        toks = []
        for i, p in enumerate(parts):
            if i >= len(ptype[1]):
                break
            toks.append(read_token(ptype[1][i], p, lenient))
        if len(parts) > len(ptype[1]):
            raise invalid_data()
        return Token("tuple", toks)
    raise AssertionError(k)

# ---------------------------------------------------------------- ABI encode
def _pad32(data):
    rem = len(data) % 32
    if rem == 0:
        return data
    return data + b"\x00" * (32 - rem)

def token_is_dynamic(tok):
    if tok.kind in ("string", "bytes", "array"):
        return True
    if tok.kind in ("fixedarray", "tuple"):
        return any(token_is_dynamic(x) for x in tok.value)
    return False

def encode_token(tok):
    k = tok.kind
    v = tok.value
    if k == "address":
        return b"\x00" * 12 + v
    if k == "bool":
        return (1 if v else 0).to_bytes(32, "big")
    if k in ("uint", "int"):
        return v.to_bytes(32, "big")
    if k == "fixedbytes":
        return _pad32(v)
    if k == "string":
        b = v.encode("utf-8", "surrogateescape")
        return len(b).to_bytes(32, "big") + _pad32(b)
    if k == "bytes":
        return len(v).to_bytes(32, "big") + _pad32(v)
    if k == "array":
        return len(v).to_bytes(32, "big") + encode_tokens(v)
    if k in ("fixedarray", "tuple"):
        return encode_tokens(v)
    raise AssertionError(k)

def encode_tokens(tokens):
    head_size = 0
    encs = []
    for tok in tokens:
        if token_is_dynamic(tok):
            head_size += 32
            encs.append(None)
        else:
            e = encode_token(tok)
            encs.append(e)
            head_size += len(e)
    out = bytearray()
    tails = bytearray()
    offset = head_size
    for tok, e in zip(tokens, encs):
        if token_is_dynamic(tok):
            out += offset.to_bytes(32, "big")
            te = encode_token(tok)
            tails += te
            offset += len(te)
        else:
            out += e
    out += tails
    return bytes(out)

