# ---------------------------------------------------------------- function / event lookup
def find_function(contract, name_or_sig):
    if "(" in name_or_sig:
        name = name_or_sig[:name_or_sig.index("(")]
        sig_mode = True
    else:
        name = name_or_sig
        sig_mode = False
    funcs = contract.functions.get(name, [])
    if not funcs:
        raise AppError("Invalid name: " + name)
    if not sig_mode:
        if len(funcs) == 1:
            return funcs[0]
        raise AppError("More than one function found for name `%s`, try providing the full signature" % name)
    for f in funcs:
        if f.signature() == name_or_sig:
            return f
    raise AppError("invalid function signature `%s`" % name_or_sig)

def find_event(contract, name_or_sig):
    if "(" in name_or_sig:
        name = name_or_sig[:name_or_sig.index("(")]
        sig_mode = True
    else:
        name = name_or_sig
        sig_mode = False
    events = contract.events.get(name, [])
    if not events:
        raise AppError("Invalid name: " + name)
    if not sig_mode:
        if len(events) == 1:
            return events[0]
        raise AppError("More than one function found for name `%s`, try providing the full signature" % name)
    h = keccak256(name_or_sig.encode("utf-8", "surrogateescape"))
    for e in events:
        if e.sig_hash() == h:
            return e
    raise AppError("Invalid signature `0x%s\u2026%s`" % (h[:2].hex(), h[-2:].hex()))

def parse_topic(s):
    stripped = s[2:] if s.startswith("0x") else s
    bs = stripped.encode("utf-8", "surrogateescape")
    if len(bs) > 64:
        raise AppError("Invalid input length")
    for i, bch in enumerate(bs):
        if _hex_val(bch) is None:
            raise AppError("Invalid character '%s' at position %d" % (chr(bch), i))
    if len(bs) != 64:
        raise AppError("Invalid input length")
    return hex_decode(stripped)

