# ---------------------------------------------------------------- contract loading
class Param:
    __slots__ = ("name", "kind", "indexed")
    def __init__(self, name, kind, indexed=False):
        self.name = name; self.kind = kind; self.indexed = indexed
class Func:
    __slots__ = ("name", "inputs", "outputs")
    def __init__(self, name, inputs, outputs):
        self.name = name; self.inputs = inputs; self.outputs = outputs
    def signature(self):
        ins = ",".join(param_display(p.kind) for p in self.inputs)
        if not self.outputs:
            return "%s(%s)" % (self.name, ins)
        outs = ",".join(param_display(p.kind) for p in self.outputs)
        return "%s(%s):(%s)" % (self.name, ins, outs)
    def selector_sig(self):
        return "%s(%s)" % (self.name, ",".join(param_display(p.kind) for p in self.inputs))
class Event:
    __slots__ = ("name", "inputs", "anonymous")
    def __init__(self, name, inputs, anonymous):
        self.name = name; self.inputs = inputs; self.anonymous = anonymous
    def signature(self):
        return "%s(%s)" % (self.name, ",".join(param_display(p.kind) for p in self.inputs))
    def sig_hash(self):
        return keccak256(self.signature().encode("utf-8", "surrogateescape"))
class Contract:
    def __init__(self):
        self.functions = {}  # name -> [Func]
        self.events = {}
    def add_func(self, f):
        self.functions.setdefault(f.name, []).append(f)
    def add_event(self, e):
        self.events.setdefault(e.name, []).append(e)

def _follow_tuple(kind):
    while True:
        if kind[0] == "tuple":
            return True
        if kind[0] in ("array", "fixedarray"):
            kind = kind[1]; continue
        return False
def _fill_tuple(kind, comps):
    if kind[0] == "tuple":
        return pt_tuple(list(kind[1]) + list(comps))
    if kind[0] == "array":
        return pt_array(_fill_tuple(kind[1], comps))
    if kind[0] == "fixedarray":
        return pt_fixed_array(_fill_tuple(kind[1], comps), kind[2])
    return kind

class OpCtx:
    def __init__(self, parser, node):
        self.parser = parser; self.node = node
    def next_consumed(self):
        data = self.parser.data; n = self.parser.len
        i = self.node.end
        while i < n and data[i] in b" \t\n\r": i += 1
        if i < n and data[i] == 44:
            i += 1
            while i < n and data[i] in b" \t\n\r": i += 1
        if i < n:
            return i + 1
        return i
    def err(self, msg):
        line, col = self.parser.position(self.next_consumed())
        raise SerdeError("%s at line %d column %d" % (msg, line, col))
    def err_consumed(self, msg, consumed):
        line, col = self.parser.position(consumed)
        raise SerdeError("%s at line %d column %d" % (msg, line, col))

