def load_contract_from_bytes(data):
    parser = JsonParser(data)
    parser.skip_ws()
    if parser.pos >= parser.len:
        parser.error("EOF while parsing a value", parser.pos)
    first = parser.data[parser.pos]
    if first != 91:  # '['
        if first == 123:  # '{'
            consumed = min(parser.len, parser.pos + 2)
            parser.error("invalid type: map, expected valid abi spec file", consumed)
        node = parser.parse_value()
        # root primitive/array mismatch (array handled above; string/number/bool/null/object handled)
        parser.error("invalid type: %s, expected valid abi spec file" % unexpected_str(node), node.end)
    parser.pos += 1
    loader = ContractLoader(parser)
    # array elements, streamed
    parser.skip_ws()
    if parser.pos >= parser.len:
        parser.error("EOF while parsing a list", parser.pos)
    if parser.data[parser.pos] == 93:
        parser.pos += 1
    else:
        while True:
            elem = parser.parse_value()
            loader.convert_operation(elem)
            parser.skip_ws()
            if parser.pos >= parser.len:
                parser.error("EOF while parsing a list", parser.pos)
            c = parser.data[parser.pos]
            if c == 44:
                parser.pos += 1
                continue
            if c == 93:
                parser.pos += 1
                break
            parser.error("expected `,` or `]`", parser.pos + 1)
    parser.skip_ws()
    if parser.pos < parser.len:
        parser.error("trailing characters", parser.pos + 1)
    return loader.contract

def load_contract(path):
    pbytes = os.fsencode(path)
    try:
        if os.path.isdir(pbytes):
            raise IsADirectoryError(21, "Is a directory")
        with open(pbytes, "rb") as fh:
