    except IsADirectoryError:
        msg = "Is a directory (os error 21)"
        raise AppError("Serialization error: " + msg, msg)
    except OSError as e:
        msg = "%s (os error %d)" % (e.strerror or str(e), e.errno or 1)
        raise AppError(msg)
