def _jaro(s1, s2):
    if s1 == s2:
        return 1.0
    l1, l2 = len(s1), len(s2)
    if l1 == 0 or l2 == 0:
        return 0.0
    md = max(l1, l2) // 2 - 1
    if md < 0: md = 0
    m1 = [False] * l1; m2 = [False] * l2
    matches = 0
    for i in range(l1):
        lo = max(0, i - md); hi = min(l2, i + md + 1)
        for j in range(lo, hi):
            if not m2[j] and s1[i] == s2[j]:
                m1[i] = True; m2[j] = True; matches += 1; break
    if matches == 0:
        return 0.0
    t = 0; kidx = 0
    for i in range(l1):
        if m1[i]:
            while not m2[kidx]: kidx += 1
            if s1[i] != s2[kidx]: t += 1
            kidx += 1
    t //= 2
    return (matches / l1 + matches / l2 + (matches - t) / matches) / 3.0
