import subprocess, json, glob
ORIG="/tmp/origdir/executable"; NEW="/tmp/newdir/executable"
def run(b,args):
 p=subprocess.run([b]+args,capture_output=True,text=True); return p.returncode,p.stdout,p.stderr
def gen(kind):
 # kind display-ish dict from abi input type + components
 t=kind
 # use type string from abi (approx)
 return None
cases=[]
for path in sorted(glob.glob("assets/*.abi")):
 abi=json.load(open(path))
 for e in abi:
  if e.get("type")!="function": continue
  vals=[]
  ok=True
  for inp in e.get("inputs",[]):
   t=inp["type"]
   if t=="bool": vals.append("true")
   elif t=="address": vals.append("1234567890abcdef1234567890abcdef12345678")
   elif t=="string": vals.append("hello")
   elif t=="bytes": vals.append("1234abcd")
   elif t.startswith("bytes"): vals.append("ab"*int(t[5:] or 1) if t[5:].isdigit() else "1234")
   elif t.startswith("uint") or t.startswith("int"): vals.append("00"*31+"2a")
   elif t.endswith("[]"): vals.append("["+",".join([gen_dummy(t[:-2])]*2)+"]")
   elif "[" in t:
       dummy=gen_dummy(t[:t.index("[")]); n=int(t[t.index("[")+1:t.index("]")]); vals.append("["+",".join([dummy]*n)+"]")
   elif t=="tuple":
       vals.append("("+",".join(gen_dummy(c["type"]) for c in inp.get("components",[]))+")")
   else: vals.append("true")
  args=["encode","function",path,e["name"]]
  for v in vals: args+=["-p",v]
  cases.append(args)
  argsl=["encode","function",path,e["name"],"-l"]
  # lenient values are different: use same but numbers in strict format would be interpreted as len64 hex OK, address bytes... just append
  for v in vals: argsl+=["-p",v]
  cases.append(argsl)
def dummy(): pass
def gen_dummy(t):
 if t=="bool": return "true"
 if t=="address": return "1234567890abcdef1234567890abcdef12345678"
 if t=="string": return "hello"
 if t=="bytes": return "1234"
 if t.startswith("bytes") and t[5:].isdigit(): return "ab"*int(t[5:])
 if t.startswith("uint") or t.startswith("int"): return "00"*31+"01"
 return "true"
fails=0
for args in cases:
 a=run(ORIG,args); b=run(NEW,args)
 if a!=b:
  fails+=1; print("DIFF",args); print(" orig",a); print(" new",b)
print(len(cases),fails)
